beginning.embedded_functions:
//each function name should be prefixed by em_

// Function to check if the NGSetupRequest message rate exceeds a threshold
static inline int em_check_ngsetup_rate(uint64_t timestamp, uint64_t counter) {
  // Define a threshold for the number of NGSetupRequest messages within a time window
  static const uint32_t rate_threshold = 5;
  // Define a time window in milliseconds
  static const uint32_t time_window = 1000;

  static uint64_t last_timestamp = 0;
  static uint32_t message_count = 0;

  if (timestamp > last_timestamp) {
    uint32_t elapsed_time = (uint32_t)(timestamp - last_timestamp);
    if (elapsed_time >= time_window) {
      message_count = 0;
      last_timestamp = timestamp;
    }
  }

  message_count++;

  if (message_count > rate_threshold) {
    return 1; // Exceeds the threshold
  } else {
    return 0; // Within the threshold
  }
}
